// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 time, address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(c) && actor != address(0));
        time = bound(time, 1, 2_000_000_000);
        amount = bound(amount, 0, 100 ether);
        unlockTime = bound(unlockTime, 0, 2_000_000_000);

        vm.warp(time);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        (uint256 storedUnlockTime, ) = c.Acc(actor);
        uint256 expected = unlockTime > time ? unlockTime : time;
        assertTrue(storedUnlockTime == expected, "unlockTime must be clamped to max(unlockTime, now) after Put");
    }
}
